static java.util.List<Integer> topValues(int[] values,int k) {
    java.util.HashMap<Integer,Integer> counts=new java.util.HashMap<>();
    for(int n:values)counts.put(n,counts.getOrDefault(n,0)+1);
    java.util.PriorityQueue<Integer> queue=new java.util.PriorityQueue<>((a,b)-> {
        int order=Integer.compare(counts.get(b),counts.get(a));return order!=0?order:Integer.compare(a,b);
    }
    );
    queue.addAll(counts.keySet());
    java.util.List<Integer> out=new java.util.ArrayList<>();
    while(out.size()<k&&!queue.isEmpty())out.add(queue.remove());
    return out;
}

