static abstract class Accumulator {
    abstract int sum(int[] values);
}
static class LoopSum extends Accumulator {
    @Override int sum(int[] values) {
        int total=0;
        for(int n:values)total+=n;
        return total;
    }
}
static int abstractSum(int[] values) {
    Accumulator operation=new LoopSum();
    return operation.sum(values);
}

static int maxSquare(int[][] grid) {
    if(grid.length==0)return 0;
    int rows=grid.length,cols=grid[0].length,best=0;
    int[][] dp=new int[rows+1][cols+1];
    for(int r=1;r<=rows;r++)for(int c=1;c<=cols;c++) {
        if(grid[r-1][c-1]==1) {
            dp[r][c]=1+Math.min(dp[r-1][c],Math.min(dp[r][c-1],dp[r-1][c-1]));
            best=Math.max(best,dp[r][c]);
        }
    }
    return best*best;
}

